WebcompatReporterHandlerAsyncWaiter::WebcompatReporterHandlerAsyncWaiter(
    WebcompatReporterHandler* proxy) : proxy_(proxy) {}

WebcompatReporterHandlerAsyncWaiter::~WebcompatReporterHandlerAsyncWaiter() = default;


void WebcompatReporterHandlerAsyncWaiter::GetBrowserParams(
    std::optional<std::string>* out_contact_info, bool* out_contact_info_save_flag, std::vector<std::string>* out_components) {
  base::RunLoop loop;
  proxy_->GetBrowserParams(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::optional<std::string>* out_contact_info
,
             bool* out_contact_info_save_flag
,
             std::vector<std::string>* out_components
,
             const std::optional<std::string>& contact_info,
             bool contact_info_save_flag,
             const std::vector<std::string>& components) {*out_contact_info = std::move(contact_info);*out_contact_info_save_flag = std::move(contact_info_save_flag);*out_components = std::move(components);
            loop->Quit();
          },
          &loop,
          out_contact_info,
          out_contact_info_save_flag,
          out_components));
  loop.Run();
}



void WebcompatReporterHandlerAsyncWaiter::GetWebcompatCategories(
    std::vector<WebcompatCategoryItemPtr>* out_categories) {
  base::RunLoop loop;
  proxy_->GetWebcompatCategories(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<WebcompatCategoryItemPtr>* out_categories
,
             std::vector<WebcompatCategoryItemPtr> categories) {*out_categories = std::move(categories);
            loop->Quit();
          },
          &loop,
          out_categories));
  loop.Run();
}

std::vector<WebcompatCategoryItemPtr> WebcompatReporterHandlerAsyncWaiter::GetWebcompatCategories(
    ) {
  std::vector<WebcompatCategoryItemPtr> async_wait_result;
  GetWebcompatCategories(&async_wait_result);
  return async_wait_result;
}






